describe('Form Submission Success Feedback', () => {
    beforeEach(() => {
        cy.visit('/form-page'); // Replace with the actual URL of the form page
    });

    it('should display success feedback after valid form submission', () => {
        cy.get('input[name="username"]').type('validUser');
        cy.get('input[name="email"]').type('valid@example.com');
        cy.get('input[name="password"]').type('ValidPassword123');
        cy.get('form').submit();

        cy.get('.success-message').should('be.visible')
            .and('contain', 'Form submitted successfully!');
    });

    it('should not display success feedback for invalid form submission', () => {
        cy.get('input[name="username"]').type(''); // Invalid username
        cy.get('input[name="email"]').type('invalid-email'); // Invalid email
        cy.get('input[name="password"]').type('123'); // Invalid password
        cy.get('form').submit();

        cy.get('.success-message').should('not.exist');
        cy.get('.error-message').should('be.visible')
            .and('contain', 'Please correct the errors and try again.');
    });
});
